package com.example.commerce.order.settlements;
import static com.example.commerce.order.settlements.SettlementModels.*;import java.time.LocalDate;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/settlements") public class SettlementController{private final SettlementService service;public SettlementController(SettlementService service){this.service=service;}@GetMapping public SettlementPage list(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return service.list(from,to);}@PostMapping("/rebuild") public RebuildResult rebuild(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return service.rebuild(from,to);}}
